import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { BeforeInsert, BeforeUpdate, Column, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity()
class Post {
    @PrimaryGeneratedColumn() id: number
    @Column() title: string
    @Column() slug: string

    @BeforeInsert() @BeforeUpdate()
    makeSlug() { this.slug = this.title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") }
}

@Injectable()
class Demo {
    constructor(@InjectRepository(Post) private readonly repo: Repository<Post>) {}
    async run() {
        const p = await this.repo.save(this.repo.create({ title: "NestJS va TypeORM: Boshlanish" }))
        console.log("slug:", p.slug)
        p.title = "Yangi sarlavha 2026"
        console.log("yangilangan slug:", (await this.repo.save(p)).slug)
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Post], synchronize: true }), TypeOrmModule.forFeature([Post])], providers: [Demo] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(Demo).run()
    await app.close()
}
main()

