import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Order { @PrimaryGeneratedColumn() id: number; @Column() total: number }
@Entity() class AuditLog { @PrimaryGeneratedColumn() id: number; @Column() action: string }

@Injectable()
class Demo {
    constructor(
        @InjectRepository(Order) private readonly orders: Repository<Order>,
        @InjectRepository(AuditLog, "audit") private readonly logs: Repository<AuditLog>,
    ) {}
    async run() {
        const o = await this.orders.save({ total: 90000 })
        await this.logs.save({ action: `order#${o.id} created` })
        console.log("asosiy baza:", await this.orders.count(), "| audit bazasi:", await this.logs.find())
    }
}

@Module({
    imports: [
        TypeOrmModule.forRoot({ type: "sqljs", entities: [Order], synchronize: true }),
        TypeOrmModule.forRoot({ name: "audit", type: "sqljs", entities: [AuditLog], synchronize: true }),
        TypeOrmModule.forFeature([Order]),
        TypeOrmModule.forFeature([AuditLog], "audit"),
    ],
    providers: [Demo],
})
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(Demo).run()
    await app.close()
}
main()

