// Buyruqlar:
//   npx typeorm migration:generate src/migrations/AddPhone -d dist/data-source.js
//   npx typeorm migration:run -d dist/data-source.js
//   npx typeorm migration:revert -d dist/data-source.js

import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { TypeOrmModule } from "@nestjs/typeorm"
import { DataSource, MigrationInterface, QueryRunner, Table, TableColumn } from "typeorm"

class CreateUsers1700000000000 implements MigrationInterface {
    async up(q: QueryRunner) {
        await q.createTable(new Table({ name: "users", columns: [{ name: "id", type: "integer", isPrimary: true, isGenerated: true, generationStrategy: "increment" }, { name: "email", type: "varchar" }] }))
    }
    async down(q: QueryRunner) { await q.dropTable("users") }
}
class AddPhone1700000000001 implements MigrationInterface {
    async up(q: QueryRunner) { await q.addColumn("users", new TableColumn({ name: "phone", type: "varchar", isNullable: true })) }
    async down(q: QueryRunner) { await q.dropColumn("users", "phone") }
}

@Injectable() class Demo {
    constructor(private readonly ds: DataSource) {}
    async run() {
        const applied = await this.ds.runMigrations()
        console.log("bajarildi:", applied.map(m => m.name))
        console.log("ustunlar:", (await this.ds.query("PRAGMA table_info(users)")).map((c: { name: string }) => c.name))
        await this.ds.undoLastMigration()
        console.log("revert'dan keyin:", (await this.ds.query("PRAGMA table_info(users)")).map((c: { name: string }) => c.name))
    }
}
@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", migrations: [CreateUsers1700000000000, AddPhone1700000000001], synchronize: false })], providers: [Demo] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(Demo).run()
    await app.close()
}
main()

