import { Column, DataSource, DefaultNamingStrategy, Entity, PrimaryGeneratedColumn } from "typeorm"

class SnakeNaming extends DefaultNamingStrategy {
    columnName(prop: string, custom: string | undefined, prefixes: string[]) { return custom ?? [...prefixes, prop].join("_").replace(/[A-Z]/g, c => "_" + c.toLowerCase()) }
    tableName(target: string, userSpecified: string | undefined) { return userSpecified ?? target.replace(/[A-Z]/g, (c, i) => (i ? "_" : "") + c.toLowerCase()) + "s" }
}
@Entity() class OrderItem { @PrimaryGeneratedColumn() id!: number; @Column() productName!: string; @Column() unitPrice!: number }

