import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Between, Column, Entity, In, IsNull, Like, MoreThan, Not, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Product {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @Column("int") price: number
    @Column({ type: "text", nullable: true }) brand: string | null
}

@Injectable()
class Demo {
    constructor(@InjectRepository(Product) private readonly repo: Repository<Product>) {}
    async run() {
        await this.repo.save([
            { name: "Telefon A", price: 3000000, brand: "Samsung" },
            { name: "Telefon B", price: 1500000, brand: "Xiaomi" },
            { name: "Quloqchin", price: 200000, brand: null },
            { name: "Planshet", price: 4500000, brand: "Samsung" },
        ])
        const names = (list: Product[]) => list.map(p => p.name)
        console.log("> 2 mln:", names(await this.repo.findBy({ price: MoreThan(2000000) })))
        console.log("1–3.5 mln:", names(await this.repo.findBy({ price: Between(1000000, 3500000) })))
        console.log("'Telefon%':", names(await this.repo.findBy({ name: Like("Telefon%") })))
