import { Column, DataSource, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Wallet { @PrimaryGeneratedColumn() id: number; @Column() owner: string; @Column("int") balance: number }

@Injectable()
class Demo {
    constructor(@InjectRepository(Wallet) private readonly repo: Repository<Wallet>, private readonly ds: DataSource) {}
    async transfer(from: number, to: number, amount: number) {
        await this.ds.transaction(async em => {
            await em.decrement(Wallet, { id: from }, "balance", amount)
            const sender = await em.findOneByOrFail(Wallet, { id: from })
            if (sender.balance < 0) throw new Error("Mablag' yetarli emas")
            await em.increment(Wallet, { id: to }, "balance", amount)
        })
    }
    async show(label: string) { console.log(label, (await this.repo.find()).map(w => `${w.owner}=${w.balance}`).join(", ")) }
    async run() {
        await this.repo.save([{ owner: "Ali", balance: 100000 }, { owner: "Vali", balance: 20000 }])
        await this.transfer(1, 2, 30000)
        await this.show("30 000 o'tkazildi:")
        try { await this.transfer(1, 2, 500000) } catch (e: any) { console.log("xato:", e.message) }
        await this.show("rollback'dan keyin:")
    }
}

