import { Column, DataSource, Entity, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Stock { @PrimaryGeneratedColumn() id!: number; @Column() item!: string; @Column() qty!: number }

async function main() {
    const ds = await new DataSource({ type: "sqljs", entities: [Stock], synchronize: true }).initialize()
    await ds.getRepository(Stock).save({ item: "olma", qty: 5 })
    const qr = ds.createQueryRunner()
    await qr.connect()
    await qr.startTransaction()
    try {
        await qr.manager.decrement(Stock, { id: 1 }, "qty", 3)
        const left = (await qr.manager.findOneBy(Stock, { id: 1 }))!.qty
        if (left < 0) throw new Error("yetarli emas")
        await qr.commitTransaction()
        console.log("commit, qoldiq:", left)
    } catch (e) {
        await qr.rollbackTransaction()
        console.log("rollback:", (e as Error).message)
    } finally { await qr.release() }
    await ds.destroy()
}
