import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, ManyToOne, OneToMany, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Author {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @OneToMany(() => Book, b => b.author) books: Book[]
}

@Entity() class Book {
    @PrimaryGeneratedColumn() id: number
    @Column() title: string
    @ManyToOne(() => Author, a => a.books) author: Author
}

@Injectable()
class Demo {
    constructor(@InjectRepository(Author) private readonly authors: Repository<Author>, @InjectRepository(Book) private readonly books: Repository<Book>) {}
    async run() {
        const qodiriy = await this.authors.save({ name: "Abdulla Qodiriy" })
        await this.books.save([{ title: "O'tkan kunlar", author: qodiriy }, { title: "Mehrobdan chayon", author: qodiriy }])
        console.log("relations'siz:", JSON.stringify(await this.authors.findOneBy({ id: 1 })))
        console.log("relations bilan:", JSON.stringify(await this.authors.findOne({ where: { id: 1 }, relations: { books: true } })))
    }
}

@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Author, Book], synchronize: true }), TypeOrmModule.forFeature([Author, Book])], providers: [Demo] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(Demo).run()
    await app.close()
}
main()

