@Entity() @Tree("closure-table")
class Category {
    @PrimaryGeneratedColumn() id: number
    @Column() name: string
    @TreeChildren() children: Category[]
    @TreeParent() parent: Category | null
}

@Injectable() class Demo {
    constructor(@InjectDataSource() private readonly ds: DataSource) {}
    async run() {
        const repo = this.ds.getTreeRepository(Category)
        const root = await repo.save(repo.create({ name: "Elektronika" }))
        const phones = await repo.save(repo.create({ name: "Telefonlar", parent: root }))
        await repo.save(repo.create({ name: "Android", parent: phones }))
        await repo.save(repo.create({ name: "Noutbuklar", parent: root }))
        const tree = await repo.findDescendantsTree(root)
        const print = (c: Category, d = 0): string[] => [`${"  ".repeat(d)}${c.name}`, ...c.children.flatMap(x => print(x, d + 1))]
        console.log(print(tree).join("\n"))
        console.log("Android'ning ajdodlari:", (await repo.findAncestors((await repo.findOneByOrFail({ name: "Android" })))).map(c => c.name))
    }
}
