import { Column, DataSource, Entity, ManyToOne, OneToMany, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Order { @PrimaryGeneratedColumn() id!: number; @OneToMany(() => Line, l => l.order, { cascade: true }) lines!: Line[] }
@Entity() class Line { @PrimaryGeneratedColumn() id!: number; @Column() sku!: string; @ManyToOne(() => Order, o => o.lines, { orphanedRowAction: "delete" }) order!: Order }

async function main() {
    const ds = await new DataSource({ type: "sqljs", entities: [Order, Line], synchronize: true }).initialize()
    const repo = ds.getRepository(Order)
    const o = (await repo.save({ lines: [{ sku: "A" }, { sku: "B" }, { sku: "C" }] })) as Order
    o.lines = o.lines.filter(l => l.sku !== "B")
    await repo.save(o)
    console.log("qatorlar jadvali:", (await ds.getRepository(Line).find()).map(l => l.sku))
    await ds.destroy()
}
main()

