import { Column, DataSource, Entity, ManyToOne, OneToMany, PrimaryGeneratedColumn } from "typeorm"

@Entity() class Author { @PrimaryGeneratedColumn() id!: number; @Column() name!: string; @OneToMany(() => Book, b => b.author) books!: Book[]; bookIds?: number[] }
