async function main() {
    const ds = await new DataSource({ type: "sqljs", entities: [Tag, Post], synchronize: true }).initialize()
    const [nest, ts, orm] = await ds.getRepository(Tag).save([{ name: "nest" }, { name: "ts" }, { name: "orm" }])
