// Relation<T> — design:type metadata'da klassga erta murojaat (TDZ) bo'lmasligi uchun
@Entity() class User { @PrimaryGeneratedColumn() id!: number; @Column() email!: string; @OneToOne(() => Passport, p => p.owner) passport!: Relation<Passport> }
