import { Column, DataSource, Entity, PrimaryGeneratedColumn, Tree, TreeChildren, TreeParent } from "typeorm"

@Entity() @Tree("closure-table") class Category {
    @PrimaryGeneratedColumn() id!: number
    @Column() name!: string
    @TreeChildren() children!: Category[]
    @TreeParent() parent!: Category
}

async function main() {
    const ds = await new DataSource({ type: "sqljs", entities: [Category], synchronize: true }).initialize()
    const repo = ds.getTreeRepository(Category)
    const a = await repo.save(repo.create({ name: "Kiyim" }))
    const b = await repo.save(repo.create({ name: "Erkaklar", parent: a }))
    const c = await repo.save(repo.create({ name: "Ko'ylaklar", parent: b }))
    const path = await repo.findAncestors(c)
    console.log(path.sort((x, y) => x.id - y.id).map(p => p.name).join(" › "))
    await ds.destroy()
}
main()

