@Entity() class Courier { @PrimaryGeneratedColumn() id!: number; @Column() name!: string }
@Entity() class Delivery { @PrimaryGeneratedColumn() id!: number; @Column() address!: string; @ManyToOne(() => Courier) courier!: Courier }

async function main() {
    const ds = await new DataSource({ type: "sqljs", entities: [Courier, Delivery], synchronize: true }).initialize()
    const [aziz, bek] = await ds.getRepository(Courier).save([{ name: "Aziz" }, { name: "Bek" }])
    const d = await ds.getRepository(Delivery).save({ address: "Yunusobod 12", courier: aziz })
    await ds.getRepository(Delivery).update(d.id, { courier: { id: bek.id } })
    console.log((await ds.getRepository(Delivery).findOne({ where: { id: d.id }, relations: { courier: true } }))!.courier.name)
    await ds.destroy()
}
main()

