import { Column, DataSource, Entity, ManyToOne, PrimaryGeneratedColumn } from "typeorm"

@Entity() class User { @PrimaryGeneratedColumn() id!: number; @Column() name!: string }
@Entity() class Transfer {
    @PrimaryGeneratedColumn() id!: number
    @Column() amount!: number
    @ManyToOne(() => User, { eager: true }) sender!: User
    @ManyToOne(() => User, { eager: true }) receiver!: User
}

async function main() {
    const ds = await new DataSource({ type: "sqljs", entities: [User, Transfer], synchronize: true }).initialize()
    const [ali, vali] = await ds.getRepository(User).save([{ name: "Ali" }, { name: "Vali" }])
    await ds.getRepository(Transfer).save([{ amount: 50000, sender: ali, receiver: vali }, { amount: 20000, sender: vali, receiver: ali }])
    console.log((await ds.getRepository(Transfer).find({ order: { id: "ASC" } })).map(t => `${t.sender.name} → ${t.receiver.name}: ${t.amount}`))
    await ds.destroy()
}
