import { Body, Controller, Delete, Get, Injectable, Module, NotFoundException, OnModuleInit, Param, ParseIntPipe, Patch, Post } from "@nestjs/common"
import { Prisma, PrismaClient } from "@prisma/client"

@Injectable()
class PrismaService extends PrismaClient implements OnModuleInit {
    async onModuleInit() { await this.$connect() }
}

@Injectable()
class ProductsService {
    constructor(private readonly prisma: PrismaService) {}
    create(data: Prisma.ProductCreateInput) { return this.prisma.product.create({ data }) }
    findAll() { return this.prisma.product.findMany({ orderBy: { id: "asc" } }) }
    async findOne(id: number) {
        const p = await this.prisma.product.findUnique({ where: { id } })
        if (!p) throw new NotFoundException(`Mahsulot #${id} topilmadi`)
        return p
    }
    async update(id: number, data: Prisma.ProductUpdateInput) { await this.findOne(id); return this.prisma.product.update({ where: { id }, data }) }
    async remove(id: number) { await this.findOne(id); await this.prisma.product.delete({ where: { id } }); return { deleted: id } }
}

@Controller("products")
class ProductsController {
    constructor(private readonly s: ProductsService) {}
    @Post() create(@Body() b: Prisma.ProductCreateInput) { return this.s.create(b) }
    @Get() all() { return this.s.findAll() }
    @Get(":id") one(@Param("id", ParseIntPipe) id: number) { return this.s.findOne(id) }
    @Patch(":id") update(@Param("id", ParseIntPipe) id: number, @Body() b: Prisma.ProductUpdateInput) { return this.s.update(id, b) }
    @Delete(":id") remove(@Param("id", ParseIntPipe) id: number) { return this.s.remove(id) }
}

@Module({ controllers: [ProductsController], providers: [PrismaService, ProductsService] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/products", { name: "Choynak", price: 150000, category: "oshxona" })
    await http.post("/products", { name: "Piyola", price: 25000, stock: 12, category: "oshxona" })
    await http.patch("/products/1", { stock: 5 })
    await http.delete("/products/2")
    await http.get("/products")
    await http.get("/products/2")
    await http.close()
}
main()

