import { ArgumentsHost, Catch, Controller, Delete, ExceptionFilter, Injectable, Module, Param, ParseIntPipe } from "@nestjs/common"
import { Prisma, PrismaClient } from "@prisma/client"

@Catch(Prisma.PrismaClientKnownRequestError)
class PrismaErrorFilter implements ExceptionFilter {
    private readonly map: Record<string, [number, string]> = {
        P2002: [409, "Takroriy qiymat"],
        P2025: [404, "Yozuv topilmadi"],
        P2003: [400, "Bog'langan yozuv mavjud emas"],
    }
    catch(e: Prisma.PrismaClientKnownRequestError, host: ArgumentsHost) {
        const [status, message] = this.map[e.code] ?? [500, "Baza xatosi"]
        host.switchToHttp().getResponse().status(status).json({ statusCode: status, message, code: e.code })
    }
}

