import { PrismaClient } from "@prisma/client"

const prisma = new PrismaClient()

async function transfer(from: number, to: number, amount: number) {
    return prisma.$transaction(async tx => {
        const sender = await tx.account.update({ where: { id: from }, data: { balance: { decrement: amount } } })
        if (sender.balance < 0) throw new Error(`Mablag' yetarli emas (${sender.owner})`)
        await tx.account.update({ where: { id: to }, data: { balance: { increment: amount } } })
    })
}

async function show(label: string) {
    const list = await prisma.account.findMany({ orderBy: { id: "asc" } })
    console.log(label, list.map(a => `${a.owner}=${a.balance}`).join(", "))
}

async function main() {
    await prisma.account.createMany({ data: [{ owner: "Ali", balance: 100000 }, { owner: "Vali", balance: 20000 }] })
    await transfer(1, 2, 30000)
    await show("o'tkazmadan keyin:")
    try { await transfer(1, 2, 900000) } catch (e: any) { console.log("xato:", e.message) }
    await show("rollback'dan keyin:")
    await prisma.$disconnect()
}
main()

