import { Body, Controller, Delete, Get, Injectable, Module, NotFoundException, Param, Patch, Post } from "@nestjs/common"
import { InjectModel, MongooseModule, Prop, Schema, SchemaFactory } from "@nestjs/mongoose"
import { isValidObjectId, Model } from "mongoose"

@Schema({ versionKey: false })
class Note {
    @Prop({ required: true }) text: string
    @Prop({ default: false }) done: boolean
}
const NoteSchema = SchemaFactory.createForClass(Note)

@Injectable()
class NotesService {
    constructor(@InjectModel(Note.name) private readonly notes: Model<Note>) {}
    private async byId(id: string) {
        const note = isValidObjectId(id) ? await this.notes.findById(id, { _id: 0 }).lean() : null
        if (!note) throw new NotFoundException("Eslatma topilmadi")
        return note
    }
    create(text: string) { return this.notes.create({ text }) }
    findOne(id: string) { return this.byId(id) }
    async update(id: string, patch: Partial<Note>) {
        const n = await this.notes.findByIdAndUpdate(id, patch, { returnDocument: "after", projection: { _id: 0 } }).lean()
        if (!n) throw new NotFoundException("Eslatma topilmadi")
        return n
    }
    async remove(id: string) {
        const r = await this.notes.findByIdAndDelete(id)
        if (!r) throw new NotFoundException("Eslatma topilmadi")
        return { deleted: true }
    }
}

@Controller("notes")
class NotesController {
    constructor(private readonly s: NotesService) {}
    @Post() async create(@Body("text") t: string) { const n = await this.s.create(t); return { id: n.id } }
    @Get(":id") findOne(@Param("id") id: string) { return this.s.findOne(id) }
    @Patch(":id") update(@Param("id") id: string, @Body() b: Partial<Note>) { return this.s.update(id, b) }
    @Delete(":id") remove(@Param("id") id: string) { return this.s.remove(id) }
}

@Module({
    imports: [
        MongooseModule.forRootAsync({ useFactory: async () => ({ uri: await startMongo() }) }),
        MongooseModule.forFeature([{ name: Note.name, schema: NoteSchema }]),
    ],
    controllers: [NotesController],
    providers: [NotesService],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const res = await fetch((await http.app.getUrl()) + "/notes", {
        method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ text: "Non olish" }),
    })
    const { id } = await res.json()
    console.log("POST /notes →", res.status, "(id — 24 belgili ObjectId:", id.length === 24, ")")
    await http.get(`/notes/${id}`)
    await http.patch(`/notes/${id}`, { done: true })
    await http.delete(`/notes/${id}`)
    await http.get(`/notes/${id}`)
    await http.get("/notes/notogri-id")
    await http.close()
}
