import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectModel, MongooseModule, Prop, Schema, SchemaFactory } from "@nestjs/mongoose"
import { Model } from "mongoose"

@Schema()
class Product {
    @Prop({ required: [true, "Nom majburiy"], trim: true }) name: string
    @Prop({ min: [0, "Narx manfiy bo'lmasin"] }) price: number
    @Prop({ enum: { values: ["food", "tech", "books"], message: "{VALUE} — noma'lum kategoriya" } }) category: string
    @Prop({ match: [/^[A-Z]{2}-\d{4}$/, "SKU formati: AB-1234"] }) sku: string
}
const ProductSchema = SchemaFactory.createForClass(Product)

@Injectable()
class Demo {
    constructor(@InjectModel(Product.name) private readonly products: Model<Product>) {}
    async run() {
        const ok = await this.products.create({ name: "  Non  ", price: 4000, category: "food", sku: "NN-0001" })
        console.log("saqlandi, nom trim qilindi:", JSON.stringify(ok.name))
        try {
            await this.products.create({ price: -5, category: "toys", sku: "123" })
        } catch (e: any) {
            for (const [field, err] of Object.entries<any>(e.errors)) console.log(`${field}: ${err.message}`)
        }
    }
}

@Module({
    imports: [
        MongooseModule.forRootAsync({ useFactory: async () => ({ uri: await startMongo() }) }),
        MongooseModule.forFeature([{ name: Product.name, schema: ProductSchema }]),
    ],
    providers: [Demo],
})
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.get(Demo).run()
    await app.close()
    await stopMongo()
}
