import { Controller, DefaultValuePipe, Get, Injectable, Module, OnModuleInit, ParseIntPipe, Query } from "@nestjs/common"
import { InjectModel, MongooseModule, Prop, Schema, SchemaFactory } from "@nestjs/mongoose"
import { Model } from "mongoose"

@Schema() class Item { @Prop() n: number }
const ItemSchema = SchemaFactory.createForClass(Item)

@Injectable()
class ItemsService implements OnModuleInit {
    constructor(@InjectModel(Item.name) private readonly items: Model<Item>) {}
    async onModuleInit() { await this.items.insertMany(Array.from({ length: 23 }, (_, i) => ({ n: i + 1 }))) }
    async page(page: number, limit: number) {
        const [data, total] = await Promise.all([
            this.items.find({}, { _id: 0, n: 1 }).sort({ n: 1 }).skip((page - 1) * limit).limit(limit).lean(),
            this.items.countDocuments(),
        ])
        return { data: data.map(d => d.n), meta: { page, limit, total, pages: Math.ceil(total / limit) } }
    }
}

@Controller("items")
class ItemsController {
    constructor(private readonly s: ItemsService) {}
    @Get() list(@Query("page", new DefaultValuePipe(1), ParseIntPipe) page: number, @Query("limit", new DefaultValuePipe(10), ParseIntPipe) limit: number) {
        return this.s.page(page, limit)
    }
}

@Module({
    imports: [
        MongooseModule.forRootAsync({ useFactory: async () => ({ uri: await startMongo() }) }),
        MongooseModule.forFeature([{ name: Item.name, schema: ItemSchema }]),
    ],
    controllers: [ItemsController],
    providers: [ItemsService],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/items?limit=5")
    await http.get("/items?page=3&limit=10")
    await http.close()
}
