import assert from "node:assert/strict"

class Product { name: string; price: number }

@Injectable()
class ProductsService {
    constructor(@InjectModel("Product") private readonly products: Model<Product>) {}
    async cheapest() {
        const list = await this.products.find().sort({ price: 1 }).limit(1).lean()
        return list[0]?.name ?? null
    }
}

async function main() {
    // find().sort().limit().lean() zanjirini taqlid qiluvchi soxta model
    const chain = { sort: () => chain, limit: () => chain, lean: async () => [{ name: "Non", price: 4000 }] }
    const m = await Test.createTestingModule({
        providers: [ProductsService, { provide: getModelToken("Product"), useValue: { find: () => chain } }],
    }).compile()
    const name = await m.get(ProductsService).cheapest()
    assert.equal(name, "Non")
    console.log("✔ cheapest() →", name)
}
