import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { InjectModel, MongooseModule, Prop, Schema, SchemaFactory } from "@nestjs/mongoose"
import { HydratedDocument, Model } from "mongoose"

@Schema({ versionKey: false }) class Product { @Prop() name: string; @Prop() price: number; @Prop() stock: number }
const ProductSchema = SchemaFactory.createForClass(Product)
ProductSchema.methods.isAvailable = function (this: HydratedDocument<Product>) { return this.stock > 0 }
ProductSchema.statics.cheaperThan = function (max: number) { return this.find({ price: { $lt: max } }).sort({ price: 1 }) }

type ProductModel = Model<Product, {}, { isAvailable(): boolean }> & { cheaperThan(max: number): Promise<HydratedDocument<Product>[]> }

@Injectable() class Demo {
    constructor(@InjectModel("Product") private readonly model: ProductModel) {}
    async run() {
        await this.model.create([{ name: "Choy", price: 25000, stock: 3 }, { name: "Non", price: 4000, stock: 0 }, { name: "Asal", price: 90000, stock: 1 }])
        const cheap = await this.model.cheaperThan(30000)
        for (const p of cheap) console.log(p.name, "| mavjud:", (p as any).isAvailable())
