import { BadRequestException, Controller, Get, Injectable, Module, Param, PipeTransform } from "@nestjs/common"
import { isValidObjectId } from "mongoose"

@Injectable() class ParseObjectIdPipe implements PipeTransform { transform(v: string) { if (!isValidObjectId(v)) throw new BadRequestException(`"${v}" ObjectId emas`); return v } }
@Controller("posts") class P { @Get(":id") one(@Param("id", ParseObjectIdPipe) id: string) { return { id, format: "to'g'ri" } } }
@Module({ controllers: [P] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/posts/6710c0ffee00000000000001")
    await http.get("/posts/123")
    await http.close()
}
main()

